import{_ as o,C as n,o as r,c as i,aj as e,G as s}from"./chunks/framework.BwH0p-pt.js";const m=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/dashboard/index.md","filePath":"2.0/dashboard/index.md","lastUpdated":1781079046000}'),d={name:"2.0/dashboard/index.md"};function l(h,t,c,p,g,u){const a=n("ImagePopup");return r(),i("div",null,[t[0]||(t[0]=e('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p>The <strong>Dashboard</strong> is the landing page you see immediately after logging in to <a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a>. It&#39;s designed as a single-screen command center: in under a second you should be able to tell <em>how big</em> your catalog is, <em>how healthy</em> it is, <em>what your team has been doing</em>, and <em>what needs attention next</em> — without clicking into any other page.</p>',2)),s(a,{src:"/assets/2.0/images/dashboard/dashboard-overview.png",alt:"Dashboard Overview"}),t[1]||(t[1]=e(`<h2 id="what-is-the-dashboard-for" tabindex="-1">What is the Dashboard for? <a class="header-anchor" href="#what-is-the-dashboard-for" aria-label="Permalink to &quot;What is the Dashboard for?&quot;">​</a></h2><p>The Dashboard exists to answer four questions the moment you log in:</p><table tabindex="0"><thead><tr><th>Question</th><th>Where the answer lives</th></tr></thead><tbody><tr><td><strong>How big is my catalog?</strong></td><td>Catalog Overview + Catalog Structure cards</td></tr><tr><td><strong>How healthy is my data?</strong></td><td>Needs Attention, Completeness, Channel Readiness</td></tr><tr><td><strong>What has the team been doing?</strong></td><td>Product Statistics, Product Activity chart, Recent Activity</td></tr><tr><td><strong>What do I do next?</strong></td><td>Welcome Banner quick actions, Needs Attention alerts, Data Transfer panel</td></tr></tbody></table><p>It&#39;s deliberately read-heavy — the Dashboard reports state, then points you at the right page to act. Every card and panel is either clickable (to jump to the relevant listing) or paired with a quick-action button.</p><h2 id="how-the-dashboard-works" tabindex="-1">How the Dashboard works <a class="header-anchor" href="#how-the-dashboard-works" aria-label="Permalink to &quot;How the Dashboard works&quot;">​</a></h2><p>The page is composed of independent <strong>widgets</strong>, each sourced from a different part of UnoPim:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ Welcome Banner   (user greeting + quick actions)  │</span></span>
<span class="line"><span>├───────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Catalog Overview   ← products + categories tables │</span></span>
<span class="line"><span>│ Catalog Structure  ← attributes, locales, channels│</span></span>
<span class="line"><span>├───────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Needs Attention    ← completeness engine          │</span></span>
<span class="line"><span>├───────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Analytics          ← product stats + 7-day chart  │</span></span>
<span class="line"><span>│ Completeness       ← per-channel completeness     │</span></span>
<span class="line"><span>│ Channel Readiness  ← per-channel ready counts     │</span></span>
<span class="line"><span>├───────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Operations         ← activity log + Job Tracker   │</span></span>
<span class="line"><span>├───────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ AI Agent button (floating, bottom-right)          │</span></span>
<span class="line"><span>│ Theme toggle (top-right, next to bell)            │</span></span>
<span class="line"><span>└───────────────────────────────────────────────────┘</span></span></code></pre></div><p>Counts and charts are computed on page load (no scheduled jobs), so the Dashboard always reflects the current state of the database.</p><h2 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h2><h3 id="welcome-banner" tabindex="-1">Welcome Banner <a class="header-anchor" href="#welcome-banner" aria-label="Permalink to &quot;Welcome Banner&quot;">​</a></h3><p>A personalised greeting — <strong>&quot;Welcome back, [Your Name]&quot;</strong> — pinned to the top of the page. It doubles as a launchpad for the three most common actions:</p><ul><li><strong>Create Product</strong> — goes straight to the product creation page.</li><li><strong>Import Data</strong> — opens the import workflow.</li><li><strong>Export Data</strong> — opens the export workflow.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use these quick-action buttons instead of navigating through the sidebar — the Dashboard is optimised to get you to work in one click.</p></div><h3 id="catalog-overview" tabindex="-1">Catalog Overview <a class="header-anchor" href="#catalog-overview" aria-label="Permalink to &quot;Catalog Overview&quot;">​</a></h3><p>Two <strong>clickable summary cards</strong> showing the size of your catalog:</p><table tabindex="0"><thead><tr><th>Card</th><th>Shows</th><th>Clicking takes you to</th></tr></thead><tbody><tr><td><strong>Total Products</strong></td><td>Count of products across all statuses and types.</td><td>Products listing page.</td></tr><tr><td><strong>Total Categories</strong></td><td>Count of categories across the whole tree.</td><td>Categories listing page.</td></tr></tbody></table><h3 id="catalog-structure" tabindex="-1">Catalog Structure <a class="header-anchor" href="#catalog-structure" aria-label="Permalink to &quot;Catalog Structure&quot;">​</a></h3><p>A row of small cards giving a structural snapshot of how the catalog is set up. Useful for spotting configuration gaps — for example, a new channel without an assigned locale.</p><table tabindex="0"><thead><tr><th>Card</th><th>What it counts</th></tr></thead><tbody><tr><td><strong>Total Attributes</strong></td><td>Product attributes defined in the system.</td></tr><tr><td><strong>Total Groups</strong></td><td>Attribute groups.</td></tr><tr><td><strong>Total Families</strong></td><td>Attribute families.</td></tr><tr><td><strong>Total Locales</strong></td><td>Locales configured across channels.</td></tr><tr><td><strong>Total Currencies</strong></td><td>Currencies set up for use in channels.</td></tr><tr><td><strong>Total Channels</strong></td><td>Sales channels configured.</td></tr></tbody></table><h3 id="needs-attention" tabindex="-1">Needs Attention <a class="header-anchor" href="#needs-attention" aria-label="Permalink to &quot;Needs Attention&quot;">​</a></h3><p>Surfaces items that need admin action <strong>right now</strong>. The most common alert is <strong>unenriched products</strong> — products missing the data required to be channel-ready. When the catalog is healthy, this section collapses and stays quiet.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Unenriched products may not be ready for distribution to your sales channels. Review this section regularly to keep the catalog shippable.</p></div><h3 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h3><h4 id="product-statistics" tabindex="-1">Product Statistics <a class="header-anchor" href="#product-statistics" aria-label="Permalink to &quot;Product Statistics&quot;">​</a></h4><p>A numerical breakdown of the catalog — the quickest way to judge health over time.</p><table tabindex="0"><thead><tr><th>Metric</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Total Products</strong></td><td>Overall product count.</td></tr><tr><td><strong>Active / Inactive</strong></td><td>How many products are currently enabled vs. disabled.</td></tr><tr><td><strong>Product Type Distribution</strong></td><td>Percentage split between simple and configurable products.</td></tr><tr><td><strong>New This Week</strong></td><td>Products created in the current week.</td></tr><tr><td><strong>With Variants</strong></td><td>Products that have variant configurations.</td></tr><tr><td><strong>Avg Completeness</strong></td><td>Average completeness score across all products.</td></tr><tr><td><strong>Enriched</strong></td><td>Number of products flagged as fully enriched.</td></tr></tbody></table><h4 id="product-activity-last-7-days" tabindex="-1">Product Activity (Last 7 Days) <a class="header-anchor" href="#product-activity-last-7-days" aria-label="Permalink to &quot;Product Activity (Last 7 Days)&quot;">​</a></h4><p>A two-line chart plotting <strong>Created</strong> vs. <strong>Updated</strong> products per day for the last seven days. Flat lines at zero are a cue that the catalog has gone quiet; spikes usually mean a bulk import or enrichment run just finished.</p><h3 id="completeness" tabindex="-1">Completeness <a class="header-anchor" href="#completeness" aria-label="Permalink to &quot;Completeness&quot;">​</a></h3><p>Shows how well your product data meets each <strong>channel&#39;s</strong> requirements, with <strong>per-locale breakdowns visible side by side</strong>. For every configured channel (e.g., <em>Default</em>, <em>Amazon</em>, <em>Flipkart</em>), the card displays:</p><ul><li>An <strong>overall channel percentage</strong> as a circular gauge.</li><li><strong>Per-locale rows</strong> — one row per locale assigned to that channel (e.g., German, English, French), each with its own gauge.</li><li>A <strong>short verdict</strong> under the headline gauge:</li></ul><table tabindex="0"><thead><tr><th>Message</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Almost complete</strong></td><td>Nearly ready — only minor additions needed.</td></tr><tr><td><strong>Low completeness, add details to improve</strong></td><td>Significant product information is still missing.</td></tr></tbody></table><p>This layout makes it easy to spot the exact channel + locale combination that is blocking a product from being shippable.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Work on the lowest-scoring channel-locale pair first. A product can be ready for <em>Default</em> but still blocked on <em>Amazon → French</em> if any required attribute is missing in that specific combination.</p></div><h3 id="channel-readiness" tabindex="-1">Channel Readiness <a class="header-anchor" href="#channel-readiness" aria-label="Permalink to &quot;Channel Readiness&quot;">​</a></h3><p>A horizontal <strong>progress bar per channel</strong> reading <em>&quot;X of Y products ready&quot;</em> with a percentage (e.g., <em>&quot;2 of 3 products ready — 67%&quot;</em>). Where the Completeness widget shows <em>average quality</em>, Channel Readiness shows <em>shippable count</em> — the number of products that clear that channel&#39;s required-field bar.</p><h3 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h3><h4 id="recent-activity" tabindex="-1">Recent Activity <a class="header-anchor" href="#recent-activity" aria-label="Permalink to &quot;Recent Activity&quot;">​</a></h4><p>A chronological feed of changes across the system. Every entry captures:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Action type</strong></td><td>Created, updated, or deleted.</td></tr><tr><td><strong>Entity type</strong></td><td>Family, Attribute, Product, Category, Channel, etc.</td></tr><tr><td><strong>User name</strong></td><td>Who performed the action.</td></tr><tr><td><strong>Timestamp</strong></td><td>When it happened.</td></tr></tbody></table><p>This is the fastest way to answer <em>&quot;did someone change X recently?&quot;</em> without opening the history tab on each entity.</p><h4 id="data-transfer" tabindex="-1">Data Transfer <a class="header-anchor" href="#data-transfer" aria-label="Permalink to &quot;Data Transfer&quot;">​</a></h4><p>Status panel for your most recent import and export jobs. Each job shows one of five states:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Completed</strong></td><td>The job finished successfully.</td></tr><tr><td><strong>Processing</strong></td><td>The job is currently running.</td></tr><tr><td><strong>Pending</strong></td><td>The job is queued and waiting to start.</td></tr><tr><td><strong>Failed</strong></td><td>The job encountered errors.</td></tr><tr><td><strong>Cancelled</strong></td><td>The job was manually cancelled.</td></tr></tbody></table><p>Click <strong>&quot;View All Jobs&quot;</strong> to open the full <strong>Job Tracker</strong> with per-step progress bars and pause/resume/cancel controls.</p><h3 id="ai-agent" tabindex="-1">AI Agent <a class="header-anchor" href="#ai-agent" aria-label="Permalink to &quot;AI Agent&quot;">​</a></h3><p>A floating <strong>&quot;Open Agenting PIM&quot;</strong> button sits in the bottom-right corner of the Dashboard (and every other admin page). Clicking it opens the conversational AI Agent — type what you need in plain English and it calls the right PIM tool on your behalf.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The AI Agent can create products, enrich content, run data-quality scans, and answer questions about your catalog without you navigating the sidebar. See <strong><a href="./../ai-agent/ai-agent-chat.html">AI Agent Chat</a></strong> for the full list of 30+ tools.</p></div><h3 id="dark-light-theme" tabindex="-1">Dark / Light Theme <a class="header-anchor" href="#dark-light-theme" aria-label="Permalink to &quot;Dark / Light Theme&quot;">​</a></h3><p>UnoPim supports a <strong>Dark / Light Theme</strong> toggle. Click the sun/moon icon in the top-right corner of the header bar (next to the notification bell) to switch between light and dark mode. Your preference persists across sessions, so every page — the Dashboard, product listing, editors, and the AI Agent Chat — keeps the theme you picked.</p>`,50)),s(a,{src:"/assets/2.0/images/settings/dark-theme.png",alt:"Dark Theme"}),t[2]||(t[2]=e('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The theme toggle is global. Whichever mode you choose applies everywhere in the admin, not just the Dashboard.</p></div><h2 id="typical-dashboard-workflow" tabindex="-1">Typical Dashboard workflow <a class="header-anchor" href="#typical-dashboard-workflow" aria-label="Permalink to &quot;Typical Dashboard workflow&quot;">​</a></h2><p>A common way admins use the Dashboard at the start of a shift:</p><ol><li><strong>Check Needs Attention</strong> — clear any urgent alerts (e.g., unenriched products).</li><li><strong>Scan Completeness and Channel Readiness</strong> — pick the weakest channel/locale and plan a cleanup.</li><li><strong>Skim Recent Activity</strong> — confirm overnight jobs finished and teammates&#39; changes make sense.</li><li><strong>Open Data Transfer</strong> — watch any running imports/exports, or click through to the Job Tracker for detail.</li><li><strong>Launch work</strong> — use a Welcome Banner quick action or the AI Agent button to start the day&#39;s tasks.</li></ol><p>Following this flow turns the Dashboard into a daily triage screen rather than just a landing page.</p>',5))])}const y=o(d,[["render",l]]);export{m as __pageData,y as default};
